        if theta_gate < -0.6 or theta_gate > 0.6:
            if time_to_gate < 0.4:
                sandbox.apply_force(agent_body, (1500.0, 0.0))
            elif time_to_gate > 1.0:
                sandbox.apply_force(agent_body, (-1500.0, 0.0))

    # Final speed adjustment in brake zone (x=12.0-15.0)
    if 12.0 <= x <= 15.0:
        if vx < 0.45 or vx > 2.6:
            if vx < 0.45:
                sandbox.apply_force(agent_body, (1500.0, 0.0))
            else:
                sandbox.apply_force(agent_body, (-1500.0, 0.0))
